import csv, math, statistics
with open('ae_ip_termination_by_month.csv') as f:
    rows=list(csv.DictReader(f))
print('n', len(rows))
print('cols', list(rows[0].keys()) if rows else None)
for r in rows[:12]:
    print(r)
# Identify likely fields
keys = list(rows[0].keys()) if rows else []
def get(r, *names):
    for n in names:
        if n in r and r[n] not in (None, ''):
            return r[n]
    return None
diags = sorted(set(get(r, 'diagnosis','Diagnosis','DIAGNOSIS','group','Group') for r in rows))
print('diags', diags)
months = sorted(set(get(r, 'month','Month','duration','Duration','duration_months') for r in rows), key=lambda x: (x is None, str(x)))
print('n_months', len(months), months[:20])
# If manageable, print all rows
if len(rows) <= 120:
    for r in rows:
        print(r)
else:
    # Summarize extremes by diagnosis/month maybe
    for r in rows[:5]:
        print('sample', r)
    # Try numeric AE/Ae/ae
    ae_key = next((k for k in rows[0].keys() if k.lower() in ('ae','a/e','ae_ratio','ratio')), None)
    print('ae_key', ae_key)
    if ae_key:
        vals=[]
        for r in rows:
            try: vals.append((float(r[ae_key]), r))
            except: pass
        vals.sort()
        print('lowest')
        for v,r in vals[:15]: print(v, {k:r[k] for k in list(r.keys())[:6]})
        print('highest')
        for v,r in vals[-15:]: print(v, {k:r[k] for k in list(r.keys())[:6]})

